from flask import Flask, render_template_string

app = Flask(__name__)

HTML = r"""
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Ashes of the Dead</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:100%;height:100%;overflow:hidden;background:#080909;font-family:monospace}
body{display:flex;align-items:center;justify-content:center}
#game{width:min(100vw,1280px);height:min(100vh,720px);image-rendering:pixelated;background:#111;display:block}
</style>
</head>
<body>
<canvas id="game" width="960" height="540"></canvas>
<script>
"use strict";
const canvas=document.getElementById("game"),ctx=canvas.getContext("2d");
ctx.imageSmoothingEnabled=false;
const W=canvas.width,H=canvas.height,WORLD=12000,GROUND=430;
let state="TITLE",nameIndex=0,last=0,cameraX=0,score=0,shake=0;
const names=["Julia","May","Yumi"];
const keys={},mouse={x:W/2,y:H/2,down:false};
const bullets=[],zombies=[],particles=[],pickups=[],buildings=[];
let player,storyIndex=0;
const story=[
"The rain had not stopped for three days.",
"Four chairs stood beneath the funeral tent.",
"Only one of the four family members was still alive.",
"You were the daughter.",
"You were also a detective.",
"Then a man in black arrived.",
"He did not speak.",
"He only smiled.",
"The lights went out.",
"When they returned, the graves were open.",
"You woke inside a locked cell.",
"The city had already fallen."
];
const zones=[
[0,1800,"ABANDONED ASYLUM","#263035"],
[1800,3900,"RUINED VILLAGE","#39413c"],
[3900,6500,"NO MAN'S LAND","#403d35"],
[6500,9000,"MILITARY FRONT","#333b38"],
[9000,12000,"DEAD CITY","#303034"]
];

function clamp(v,a,b){return Math.max(a,Math.min(b,v))}
function rnd(a,b){return Math.random()*(b-a)+a}
function text(s,x,y,size=20,color="#fff",align="left"){
 ctx.font=`bold ${size}px monospace`;ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(s,x,y)
}
function zone(){for(const z of zones)if(player.x>=z[0]&&player.x<z[1])return z;return zones[4]}
function sx(x){return x-cameraX}
function overlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}

window.addEventListener("keydown",e=>{
 keys[e.key.toLowerCase()]=true;
 if([" ","arrowleft","arrowright","arrowup","arrowdown"].includes(e.key.toLowerCase()))e.preventDefault();
 if(e.key==="Enter")advance();
 if(e.key==="Escape")state=state==="PLAYING"?"PAUSED":state==="PAUSED"?"PLAYING":state;
 if(e.key.toLowerCase()==="r"&&state==="PLAYING")reload();
 if(e.key.toLowerCase()==="e"&&state==="PLAYING")interact();
 if(e.key.toLowerCase()==="q"&&state==="PLAYING")melee();
 if(state==="NAME_SELECT"){
  if(e.key==="ArrowLeft"||e.key.toLowerCase()==="a")nameIndex=(nameIndex+2)%3;
  if(e.key==="ArrowRight"||e.key.toLowerCase()==="d")nameIndex=(nameIndex+1)%3;
 }
});
window.addEventListener("keyup",e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener("mousemove",e=>{
 const r=canvas.getBoundingClientRect();
 mouse.x=(e.clientX-r.left)*W/r.width;mouse.y=(e.clientY-r.top)*H/r.height;
});
canvas.addEventListener("mousedown",e=>{if(e.button===0)mouse.down=true;if(state==="TITLE")state="NAME_SELECT"});
window.addEventListener("mouseup",()=>mouse.down=false);

function reset(){
 player={x:160,y:GROUND-70,w:34,h:70,vx:0,vy:0,speed:190,run:300,jump:-530,
 grounded:true,health:100,maxHealth:100,stamina:100,ammo:12,maxAmmo:12,reserve:84,
 fire:0,facing:1,inv:0,kills:0};
 bullets.length=0;zombies.length=0;particles.length=0;pickups.length=0;
 buildings.length=0;cameraX=0;score=0;storyIndex=0;
 for(let x=500;x<WORLD;x+=rnd(500,900))buildings.push({x,y:rnd(250,330),w:rnd(150,280),h:rnd(100,180)});
 for(let i=0;i<12;i++)spawnZombie(rnd(700,WORLD-300));
 pickups.push({x:900,y:GROUND-20,type:"ammo"},{x:1500,y:GROUND-20,type:"medkit"});
}
function advance(){
 if(state==="TITLE"){state="NAME_SELECT";return}
 if(state==="NAME_SELECT"){state="STORY";storyIndex=0;return}
 if(state==="STORY"){storyIndex++;if(storyIndex>=story.length){reset();state="PLAYING"}return}
 if(state==="DEAD"||state==="ENDING"){reset();state="PLAYING"}
}
function jump(){if(state==="PLAYING"&&player.grounded){player.vy=player.jump;player.grounded=false}}
function reload(){if(player.ammo<player.maxAmmo&&player.reserve>0){let n=Math.min(player.maxAmmo-player.ammo,player.reserve);player.ammo+=n;player.reserve-=n}}
function interact(){if(player.x>1100&&player.x<1300){state="STORY";storyIndex=10}}
function melee(){for(const z of zombies)if(Math.abs(z.x-player.x)<75&&Math.abs(z.y-player.y)<80)z.health-=35}

function shoot(){
 if(state!=="PLAYING"||player.fire>0||player.ammo<=0)return;
 player.ammo--;player.fire=.16;
 let tx=cameraX+mouse.x,ty=mouse.y,x=player.x+player.w/2+player.facing*18,y=player.y+27;
 let dx=tx-x,dy=ty-y,l=Math.hypot(dx,dy)||1;dx/=l;dy/=l;
 bullets.push({x,y,vx:dx*850,vy:dy*850,life:1.2});muzzle(x,y)
}
function damage(n){if(player.inv>0)return;player.health-=n;player.inv=.65;shake=10;if(player.health<=0){player.health=0;state="DEAD"}}
function spawnZombie(x){zombies.push({x,y:GROUND-62,w:34,h:62,health:100,hit:0,speed:rnd(35,75),attack:rnd(0,1)})}
function blood(x,y){particles.push({x,y,vx:rnd(-80,80),vy:rnd(-120,-20),life:rnd(.25,.6),c:"#a83b3b",s:rnd(2,5)})}
function muzzle(x,y){for(let i=0;i<5;i++)particles.push({x,y,vx:rnd(-60,60),vy:rnd(-60,60),life:.12,c:"#f0c95a",s:rnd(2,5)})}

function update(dt){
 if(state!=="PLAYING")return;
 let d=(keys["a"]||keys["arrowleft"]?-1:0)+(keys["d"]||keys["arrowright"]?1:0);
 let running=keys["shift"]&&player.stamina>0&&d!==0;
 player.vx=d*(running?player.run:player.speed);
 player.stamina=clamp(player.stamina+(running?-35:22)*dt,0,100);
 if(d)player.facing=d;
 if((keys[" "]||keys["w"]||keys["arrowup"])&&player.grounded)jump();
 player.vy+=1300*dt;player.x+=player.vx*dt;player.y+=player.vy*dt;
 if(player.y+player.h>=GROUND){player.y=GROUND-player.h;player.vy=0;player.grounded=true}
 player.x=clamp(player.x,0,WORLD-player.w);if(player.inv>0)player.inv-=dt;if(player.fire>0)player.fire-=dt;
 if(mouse.down)shoot();
 cameraX+=((player.x-W*.4)-cameraX)*Math.min(1,dt*5);cameraX=clamp(cameraX,0,WORLD-W);

 for(let i=bullets.length-1;i>=0;i--){
  let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let rem=b.life<=0;
  for(const z of zombies)if(!rem&&overlap({x:b.x-3,y:b.y-3,w:6,h:6},z)){
   z.health-=40;z.hit=.12;blood(z.x+17,z.y+30);rem=true;
   if(z.health<=0){player.kills++;score+=100;for(let n=0;n<8;n++)blood(z.x+17,z.y+30)}
  }
  if(rem)bullets.splice(i,1);
 }
 for(let i=zombies.length-1;i>=0;i--){
  let z=zombies[i];if(z.health<=0){zombies.splice(i,1);continue}
  if(z.hit>0)z.hit-=dt;let dx=player.x-z.x;
  if(Math.abs(dx)>42)z.x+=Math.sign(dx)*z.speed*dt;
  else{z.attack-=dt;if(z.attack<=0){damage(8);z.attack=1}}
 }
 if(zombies.length<14&&Math.random()<dt*.7){
  let x=clamp(player.x+(Math.random()<.5?-1:1)*rnd(600,1100),100,WORLD-100);spawnZombie(x)
 }
 for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
 if(shake>0)shake-=30*dt;
 if(player.x>WORLD-500)state="ENDING";
}

function background(){
 let z=zone();ctx.fillStyle=z[3];ctx.fillRect(0,0,W,H);
 ctx.fillStyle="#d4d0b8";ctx.fillRect(760,65,42,42);
 for(let x=-300;x<W+500;x+=170){
  let xx=x-(cameraX*.28%170),h=60+((x*17)%80);ctx.fillStyle="#22292a";ctx.fillRect(xx,GROUND-h,125,h);
  ctx.fillStyle="#74705e";for(let y=GROUND-h+15;y<GROUND-15;y+=24)for(let q=0;q<3;q++)ctx.fillRect(xx+15+q*35,y,9,7)
 }
 ctx.fillStyle="#282a26";ctx.fillRect(0,GROUND,W,H-GROUND);
 ctx.fillStyle="#1c1d1b";ctx.fillRect(0,GROUND+40,W,100);
 ctx.fillStyle="#77705a";for(let x=-100;x<W+300;x+=120)ctx.fillRect(x-(cameraX%120),GROUND+85,65,5);
 for(const b of buildings){let x=sx(b.x);if(x>W||x+b.w<0)continue;ctx.fillStyle="#343535";ctx.fillRect(x,b.y,b.w,b.h);ctx.fillStyle="#222";ctx.fillRect(x-8,b.y-15,b.w+16,18)}
}
function playerDraw(){
 if(player.inv>0&&Math.floor(player.inv*15)%2===0)return;
 let x=sx(player.x),y=player.y;
 ctx.fillStyle="#17191a";ctx.fillRect(x+4,y+65,12,6);ctx.fillRect(x+20,y+65,12,6);
 ctx.fillStyle="#252a30";ctx.fillRect(x+7,y+47,8,22);ctx.fillRect(x+20,y+47,8,22);
 ctx.fillStyle="#34444f";ctx.fillRect(x+5,y+25,25,27);
 ctx.fillStyle="#c69b78";ctx.fillRect(x+9,y+6,18,20);
 ctx.fillStyle="#332b29";ctx.fillRect(x+8,y+3,20,7);ctx.fillRect(x+7,y+7,5,12);
 ctx.fillStyle="#111";ctx.fillRect(x+(player.facing>0?22:10),y+13,3,3);
 ctx.fillStyle="#c69b78";ctx.fillRect(player.facing>0?x+27:x-5,y+29,10,7);
 ctx.fillStyle="#17191b";ctx.fillRect(player.facing>0?x+30:x-22,y+30,22,5);
}
function zombieDraw(z){
 let x=sx(z.x),y=z.y,c=z.hit>0?"#d98c8c":"#63775f";
 ctx.fillStyle=c;ctx.fillRect(x+7,y+20,22,31);ctx.fillRect(x+8,y+2,19,21);
 ctx.fillStyle="#242725";ctx.fillRect(x+7,y,21,6);
 ctx.fillStyle="#c93c3c";ctx.fillRect(x+11,y+10,4,3);ctx.fillRect(x+21,y+10,4,3);
 ctx.fillStyle=c;ctx.fillRect(x-5,y+25,12,8);ctx.fillRect(x+27,y+25,12,8);ctx.fillRect(x+9,y+48,7,14);ctx.fillRect(x+20,y+48,7,14);
 if(z.health<100){ctx.fillStyle="#111";ctx.fillRect(x,y-9,34,4);ctx.fillStyle="#bd4646";ctx.fillRect(x,y-9,34*clamp(z.health/100,0,1),4)}
}
function drawHUD(){
 ctx.fillStyle="#111";ctx.fillRect(18,18,220,22);ctx.fillStyle="#9f3535";ctx.fillRect(21,21,214*player.health/player.maxHealth,16);
 text(`HEALTH ${Math.ceil(player.health)}`,30,35,13);ctx.fillStyle="#111";ctx.fillRect(18,46,220,12);ctx.fillStyle="#d3ad51";ctx.fillRect(20,48,216*player.stamina/100,8);
 text(`${player.ammo} / ${player.reserve}`,W-30,40,22,"#eee","right");text(zone()[2],W/2,32,16,"#ddd","center");text(`KILLS ${player.kills}`,20,H-18,12,"#ddd");
}
function drawGame(){
 let ox=0,oy=0;if(shake>0){ox=rnd(-shake,shake);oy=rnd(-shake,shake)}
 ctx.save();ctx.translate(ox,oy);background();for(const z of zombies)if(sx(z.x)>-100&&sx(z.x)<W+100)zombieDraw(z);
 ctx.fillStyle="#f2d078";for(const b of bullets)ctx.fillRect(sx(b.x)-3,b.y-2,7,4);
 playerDraw();for(const p of particles){ctx.globalAlpha=clamp(p.life*3,0,1);ctx.fillStyle=p.c;ctx.fillRect(sx(p.x),p.y,p.s,p.s)}ctx.globalAlpha=1;ctx.restore();drawHUD();
 ctx.strokeStyle="#ddd";ctx.beginPath();ctx.moveTo(mouse.x-8,mouse.y);ctx.lineTo(mouse.x+8,mouse.y);ctx.moveTo(mouse.x,mouse.y-8);ctx.lineTo(mouse.x,mouse.y+8);ctx.stroke();
}
function title(){
 ctx.fillStyle="#080909";ctx.fillRect(0,0,W,H);text("ASHES",W/2,170,70,"#ddd","center");text("OF THE DEAD",W/2,230,50,"#a63c3c","center");
 text("A PIXELATED ZOMBIE SURVIVAL STORY",W/2,270,15,"#999","center");text("CLICK OR PRESS ENTER",W/2,370,18,"#eee","center");
}
function select(){
 ctx.fillStyle="#101315";ctx.fillRect(0,0,W,H);text("CHOOSE YOUR DETECTIVE",W/2,120,34,"#ddd","center");
 names.forEach((n,i)=>{let x=W/2+(i-1)*190;ctx.fillStyle=i===nameIndex?"#873c3c":"#292d2d";ctx.fillRect(x-70,200,140,170);ctx.fillStyle="#c69b78";ctx.fillRect(x-25,225,50,55);ctx.fillStyle="#34444f";ctx.fillRect(x-30,280,60,70);text(n,x,395,24,i===nameIndex?"#fff":"#999","center")});
 text("LEFT / RIGHT TO SELECT • ENTER TO BEGIN",W/2,470,15,"#aaa","center");
}
function storyDraw(){
 ctx.fillStyle="#090a0b";ctx.fillRect(0,0,W,H);text("ASHES OF THE DEAD",W/2,65,28,"#a5a39b","center");
 if(storyIndex<story.length){text(story[storyIndex],W/2,405,20,"#eee","center");text("ENTER / CLICK",W/2,475,12,"#777","center")}
}
function overlay(titleStr,sub){
 ctx.fillStyle="rgba(0,0,0,.75)";ctx.fillRect(0,0,W,H);text(titleStr,W/2,220,55,"#ddd","center");text(sub,W/2,300,17,"#aaa","center")
}
function draw(){
 ctx.clearRect(0,0,W,H);
 if(state==="TITLE")title();
 else if(state==="NAME_SELECT")select();
 else if(state==="STORY")storyDraw();
 else if(state==="PLAYING")drawGame();
 else if(state==="PAUSED"){drawGame();overlay("PAUSED","ESC TO CONTINUE")}
 else if(state==="DEAD")overlay("YOU DIED","PRESS ENTER TO RESTART");
 else if(state==="ENDING")overlay("THE END... FOR NOW","PRESS ENTER TO PLAY AGAIN");
}
function loop(t){let dt=last?(t-last)/1000:0;last=t;dt=Math.min(dt,.033);update(dt);draw();requestAnimationFrame(loop)}
reset();requestAnimationFrame(loop);
</script>
</body>
</html>
"""

@app.route("/")
def index():
    return render_template_string(HTML)

@app.route("/health")
def health():
    return {"status": "ok", "game": "Ashes of the Dead"}

if __name__ == "__main__":
    import os
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)))

